import React from "react";

export function BreadcrumbTrail() {
  const items = [{ label: "Home", href: "#" }, { label: "Components", href: "#" }, { label: "Navigation", href: "#", current: true }];
  return (
    <nav aria-label="Breadcrumb" className="flex items-center text-xs text-muted-foreground">
      <ol className="inline-flex items-center space-x-1 md:space-x-2">
        {items.map((item, index) => (
          <li key={item.label} className="inline-flex items-center">
            {index > 0 && <span className="mx-1 text-muted-foreground/60">/</span>}
            {item.current ? <span className="font-semibold text-foreground" aria-current="page">{item.label}</span> : <a href={item.href} className="hover:text-foreground transition-colors">{item.label}</a>}
          </li>
        ))}
      </ol>
    </nav>
  );
}
